// Vendored workflow engine: generated by scripts/sync-workflow-engine.mjs, never edited by hand. Source, commit and local patches: lib/workflow-engine/UPSTREAM.json
/** Runtime state materialized from a WorkflowDSL by init, mutated by diff. */
import { STEP_STATES, type StepStateValue, type WorkflowDSL } from '../../../dsl/types.ts';

/** A materialized step. Property names mirror the DSL so diff conditions/selectors query it directly. */
export interface StepState {
  id: string;
  title: string;
  description?: string;
  /** ISO datetime, resolved from due_on.$delta at init. */
  due_on?: string;
  /** true = active/actionable; dormant steps wait for a diff rule to activate them. */
  status: boolean;
  /**
   * Lifecycle label from the STEP_STATES vocabulary (set via PATCH or diff
   * rules). Opaque to the engine — no value carries built-in behavior.
   */
  state: StepStateValue;
  /** Author-stamped by a diff rule; the engine never sets it implicitly. */
  completed_at?: string;
  evidence_required: boolean;
  comments_required: boolean;
  /** Destination states the comment demand applies to; undefined = all. */
  comments_required_on?: StepStateValue[];
  comments_criterion?: string;
  /** Destination states the evidence demand applies to; undefined = all. */
  evidence_required_on?: StepStateValue[];
  evidence_criterion?: string;
  /** Append-only; each entry records who said what, and when. */
  comments: StepComment[];
  /** Append-only references to substantiating material. */
  evidence: StepEvidence[];
  completed_on_delta: number;
  /** Resolved assignee ids (deterministic query hits, else pending prompt). */
  assignee: string[];
  /**
   * Set when a person assigned this step by hand. `reresolve_on` then leaves it
   * alone: an operator who separated duties, or placed a named individual, has
   * made a decision the template query does not know about. A departure still
   * overrides it — the pinned person is gone.
   */
  assignee_pinned?: boolean;
}

export type MutableStepProperty =
  | 'status'
  | 'state'
  | 'completed_at'
  | 'due_on'
  | 'assignee'
  | 'evidence_required'
  | 'comments_required'
  | 'completed_on_delta';

export const isMutableStepProperty = (property: string): property is MutableStepProperty =>
  [
    'status',
    'state',
    'completed_at',
    'due_on',
    'assignee',
    'evidence_required',
    'comments_required',
    'completed_on_delta',
  ].includes(property);

const isStepStateValue = (value: unknown): value is StepStateValue =>
  typeof value === 'string' && STEP_STATES.some((state) => state === value);

export function stepPropertyValue(step: StepState, property: MutableStepProperty): unknown {
  return step[property];
}

export function setStepProperty(
  step: StepState,
  property: MutableStepProperty,
  value: unknown,
): boolean {
  switch (property) {
    case 'status':
    case 'evidence_required':
    case 'comments_required':
      if (typeof value !== 'boolean') return false;
      step[property] = value;
      return true;
    case 'state':
      if (!isStepStateValue(value)) return false;
      step.state = value;
      return true;
    case 'completed_at':
    case 'due_on':
      if (value !== null && typeof value !== 'string') return false;
      if (value === null) delete step[property];
      else step[property] = value;
      return true;
    case 'assignee':
      if (!Array.isArray(value) || !value.every((entry) => typeof entry === 'string')) return false;
      step.assignee = value;
      return true;
    case 'completed_on_delta':
      if (typeof value !== 'number') return false;
      step.completed_on_delta = value;
      return true;
  }
}

/** A reviewer's note against a step (the platform's step review comment). */
export interface StepComment {
  at: string;
  actor: string;
  text: string;
  /** The state transition this comment was recorded against, when it accompanied one. */
  on_transition?: string;
}

/**
 * A pointer to substantiating material. The engine stores no artifacts — `ref`
 * is a URI or document id resolved by whatever holds the file.
 */
export interface StepEvidence {
  at: string;
  actor: string;
  ref: string;
  on_transition?: string;
}

export interface OutboxEmail {
  kind: 'email';
  rule_priority: number;
  step_id: string;
  recipients: string[] | { pending_prompt: string };
  subject?: string;
  body?: string;
  attachments?: { $generate?: string; $search?: string };
  delivery: OutboxDelivery;
}

export interface OutboxAgent {
  kind: 'agent';
  rule_priority: number;
  step_id: string;
  agent_id: string;
  name: string;
  prompt: string;
  state?: unknown;
  delivery: OutboxDelivery;
}

export interface OutboxDelivery {
  /** Stable receiver-side deduplication key. */
  id: string;
  status: 'pending' | 'processing' | 'delivered' | 'dead_letter';
  attempts: number;
  next_attempt_at: string;
  claimed_at?: string;
  delivered_at?: string;
  last_error?: string;
}

export type OutboxEntry = OutboxEmail | OutboxAgent;

/** Stable identity of the domain object whose workflow state this instance carries. */
export interface AttachedObject {
  /** Domain discriminator such as `task`, `request`, `requirement`, or `case`. */
  type: string;
  /** Stable id in the owning service. */
  id: string;
  /** Snapshot/query context evaluated by the DSL. Kept in sync with legacy `task`. */
  data: Record<string, unknown>;
}

export interface WorkflowInstance {
  id: string;
  /** Hard tenant boundary for definitions, objects, directory queries, and instances. */
  organization_id: string;
  workflow_id: string;
  /** Immutable definition version used to materialize this instance. */
  definition_version: number;
  /** Compare-and-swap token incremented by the persistence adapter. */
  revision: number;
  created_by?: string;
  /** The generic domain object to which this materialized state is attached. */
  object: AttachedObject;
  /** Ordered manual workflows use atomic sequence commands. */
  execution_mode?: "sequence";
  /** Back-compatible alias for `object.data`; DSL queries continue to call it task. */
  task: Record<string, unknown>;
  start_id: string;
  steps: StepState[];
  /** External side effects queued by diff rules; a dispatcher drains this. */
  outbox: OutboxEntry[];
  /**
   * Step ids in canonical linear order (init.flatten_order, else declaration
   * order). For flat consumers — checklists, the platform's linear projection —
   * never for routing.
   */
  flat_order: string[];
  /**
   * Whether the instance satisfies its workflow's `init.terminal_when`.
   * Undefined when the workflow declares no completion condition — the engine
   * never infers one. Filterable via GET /instances?terminal=true|false.
   */
  terminal?: boolean;
  /** Priorities of `once: true` rules that have already fired on this instance. */
  fired_once?: number[];
  /** Durable callback/cohort idempotency markers. */
  processed_callback_events?: string[];
  /** Bounded request-deduplication ledger for mutation idempotency keys. */
  processed_requests?: Array<{ key: string; fingerprint: string; revision: number }>;
  /** prompt-resolutions the offline engine deferred (path → prompt text). */
  pending_prompts: Record<string, string>;
  history: HistoryEvent[];
  created_at: string;
  updated_at: string;
}

/**
 * IMPORTANT — what attribution does and does not prove. The engine records the
 * identity resolved by the configured `IdentityProvider`. The production
 * entrypoint verifies short-lived gateway-signed actor/organization claims;
 * tests may explicitly opt into raw compatibility headers. The trail is only
 * as trustworthy as that provider and its key custody.
 *
 * Where a history event came from:
 *   'user'   — the actor's own request acted directly on this instance
 *   'rule'   — a diff rule on this instance, triggered by `actor`'s request
 *   'cohort' — a cohort rule reached in because `origin_instance_id` changed;
 *              on a task-membership edit the origin may be the watcher itself
 * Rule-driven writes are the engine acting, but never on its own initiative:
 * every one is traceable to the request that set it off.
 */
export type HistorySource = 'user' | 'rule' | 'cohort' | 'callback' | 'provisioning';

export interface HistoryEvent {
  at: string;
  /**
   * `state_changed` is emitted for every step-state transition, whoever caused
   * it (a user PATCH or a diff/cohort rule). It is the approval log: filtering
   * `step_patched` alone would miss rule-driven transitions and would count
   * due-date edits as if they were decisions.
   */
  type:
    | 'instance_created'
    | 'step_patched'
    | 'state_changed'
    | 'comment_added'
    | 'evidence_added'
    | 'assignee_reresolved'
    | 'task_updated'
    | 'object_callback_applied'
    | 'diff_rule_fired'
    /**
     * The assignee's bounded due_on_extension was exercised. Deliberately
     * distinct from the `step_patched` row the same request also writes: the
     * once-only check counts THESE, so an administrative due-date correction
     * (which bypasses the guard) never burns the assignee's one extension.
     */
    | 'due_date_extended'
    | 'internal_set'
    | 'external_queued'
    | 'external_delivered'
    | 'external_dead_lettered';
  step_id?: string;
  detail?: string;
  data?: Record<string, unknown>;
  /** Directory id of the human whose request caused this event. */
  actor?: string;
  source?: HistorySource;
  /** For source 'cohort': the instance whose change triggered this write. */
  origin_instance_id?: string;
}

export interface RegisteredWorkflow {
  object_type?: string;
  id: string;
  organization_id: string;
  /** Monotonic, immutable version assigned by the persistence adapter. */
  version: number;
  dsl: WorkflowDSL;
  created_by?: string;
  registered_at: string;
  /**
   * Mermaid source for this definition, rendered from `dsl` once when the
   * workflow is registered. Readers render this string rather than rebuilding
   * a graph, so every surface shows the same picture of the process. Absent
   * on records registered before diagrams existed.
   */
  diagram?: string;
}
